"""Template for a QGIS Processing Algorithm."""

from qgis.core import (QgsProcessing,
                       QgsProcessingAlgorithm,
                       QgsProcessingParameterVectorLayer,
                       QgsProcessingParameterFeatureSink)
from qgis.PyQt.QtCore import QCoreApplication

class AntigravityAlgorithm(QgsProcessingAlgorithm):
    """
    Template algorithm for Antigravity-powered plugins.
    """
    INPUT = 'INPUT'
    OUTPUT = 'OUTPUT'

    def tr(self, string):
        return QCoreApplication.translate('Processing', string)

    def createInstance(self):
        return AntigravityAlgorithm()

    def name(self):
        return 'antigravity_algorithm'

    def displayName(self):
        return self.tr('Antigravity Algorithm')

    def group(self):
        return self.tr('Antigravity Scripts')

    def groupId(self):
        return 'antigravity'

    def shortHelpString(self):
        return self.tr("Example algorithm showing the standard structure.")

    def initAlgorithm(self, config=None):
        self.addParameter(
            QgsProcessingParameterVectorLayer(
                self.INPUT,
                self.tr('Input layer'),
                [QgsProcessing.TypeVectorAnyGeometry]
            )
        )

        self.addParameter(
            QgsProcessingParameterFeatureSink(
                self.OUTPUT,
                self.tr('Output layer')
            )
        )

    def processAlgorithm(self, parameters, context, feedback):
        # Implementation goes here
        source = self.parameterAsSource(parameters, self.INPUT, context)
        (sink, dest_id) = self.parameterAsSink(parameters, self.OUTPUT, context,
                                               source.fields(), source.wkbType(), source.sourceCrs())

        # Logic loop example
        feedback.pushInfo(f"Processing layer: {source.sourceName()}")

        return {self.OUTPUT: dest_id}

#!/usr/bin/env python3
"""
Bootstrap script for Antigravity-powered projects.
Automates project name replacement and environment initialization.
"""

import os
import subprocess
import sys
from pathlib import Path

def run_command(command, shell=True):
    """Run a shell command and return success."""
    try:
        subprocess.run(command, shell=shell, check=True, capture_output=True)
        return True
    except (subprocess.CalledProcessError, FileNotFoundError):
        return False

def check_environment():
    """Verify that the environment meets the minimum requirements."""
    print("🔍 Checking environment...")

    # 1. Python version check
    if sys.version_info < (3, 10):
        print(f"  ❌ Error: Python 3.10+ is required (found {sys.version_info.major}.{sys.version_info.minor})")
        return False
    print("  ✅ Python 3.10+")

    # 2. Check for uv
    if not run_command("uv --version"):
        print("  ❌ Error: `uv` is not installed. Please install it: https://github.com/astral-sh/uv")
        return False
    print("  ✅ uv found")

    return True

def setup_project():
    print("🚀 Antigravity Project Bootstrapper")
    print("-----------------------------------")

    if not check_environment():
        sys.exit(1)

    # Get project name
    project_name = input("\nEnter the new project name (e.g., my-awesome-plugin): ").strip()
    if not project_name:
        print("❌ Error: Project name cannot be empty.")
        sys.exit(1)

    # Files to process
    files_to_process = [
        Path("pyproject.toml"),
        Path("README.md"),
    ]

    # Placeholder
    placeholder = "{{PROJECT_NAME}}"

    print(f"\n📝 Replacing placeholders in {len(files_to_process)} files...")

    for file_path in files_to_process:
        if file_path.exists():
            try:
                content = file_path.read_text(encoding="utf-8")
                if placeholder in content:
                    new_content = content.replace(placeholder, project_name)
                    file_path.write_text(new_content, encoding="utf-8")
                    print(f"  ✅ Updated {file_path}")
                else:
                    print(f"  ⚠️  Placeholder not found in {file_path}")
            except Exception as e:
                print(f"  ❌ Error processing {file_path}: {e}")
        else:
            print(f"  ⚠️  File {file_path} not found.")

    # Initialize uv environment
    print("\n📦 Initializing environment with `uv sync`...")
    if run_command("uv sync"):
        print("  ✅ Environment initialized successfully.")
    else:
        print("  ❌ Error: Failed to run `uv sync`.")
        sys.exit(1)

    # Git Initialization
    print("\n🐙 Git Initialization...")
    if not Path(".git").exists():
        if run_command("git init"):
            print("  ✅ Git repository initialized.")
            if run_command("git add .") and run_command('git commit -m "initial: project setup with Antigravity Framework"'):
                print("  ✅ Initial commit created.")
    else:
        print("  ℹ️ Git repository already exists.")

    print("\n✨ Bootstrap complete! Your project is ready.")
    print("Next steps:")
    print("1. Explore AGENTS.md in scaffold/")
    print("2. Run `/inicia-sesion` to start collaborating with your agent.")

    # Self-destruct?
    delete_self = input("\nDo you want to delete this bootstrap script? (y/N): ").lower()
    if delete_self == 'y':
        try:
            os.remove(__file__)
            print("  ✅ bootstrap.py removed.")
        except Exception as e:
            print(f"  ⚠️  Could not remove bootstrap.py: {e}")

if __name__ == "__main__":
    setup_project()

