#
#  Auto-fix engine for applying code corrections.
#  ***************************************************************************/

import difflib
import pathlib
import subprocess
import tempfile
from abc import ABC, abstractmethod
from typing import Any, Dict, List

from .transformers import (
    GDALImportTransformer,
    I18nTransformer,
    LegacyImportTransformer,
    PrintToLogTransformer,
    apply_transformation,
)


def check_git_status(project_path: pathlib.Path) -> bool:
    """Checks if the Git working directory is clean.

    Args:
        project_path: Root path of the Git project.

    Returns:
        True if there are no uncommitted changes, False otherwise.
        Returns True if Git is not available.
    """
    try:
        result = subprocess.run(
            ["git", "status", "--porcelain"],
            cwd=project_path,
            capture_output=True,
            text=True,
            timeout=5,
        )
        return len(result.stdout.strip()) == 0
    except (subprocess.TimeoutExpired, FileNotFoundError):
        # Git not available or timeout
        return True  # Don't block if git is not available


def show_diff(file_path: pathlib.Path, original_content: str, new_content: str) -> None:
    """Displays a colorized unified diff between original and new content.

    Args:
        file_path: Path to the file being compared.
        original_content: The original content of the file.
        new_content: The modified content of the file.
    """
    diff = difflib.unified_diff(
        original_content.splitlines(keepends=True),
        new_content.splitlines(keepends=True),
        fromfile=f"a/{file_path.name}",
        tofile=f"b/{file_path.name}",
        lineterm="",
    )

    print("    " + "─" * 60)
    for line in diff:
        line = line.rstrip()
        if line.startswith("+++") or line.startswith("---"):
            print(f"    {line}")
        elif line.startswith("+"):
            print(f"    \033[32m{line}\033[0m")  # Green
        elif line.startswith("-"):
            print(f"    \033[31m{line}\033[0m")  # Red
        elif line.startswith("@@"):
            print(f"    \033[36m{line}\033[0m")  # Cyan
        else:
            print(f"    {line}")
    print("    " + "─" * 60)


class FixStrategy(ABC):
    """Abstract base class for all auto-fix strategies."""

    @abstractmethod
    def can_fix(self, issue: Dict[str, Any]) -> bool:
        """Returns True if this strategy can fix the given issue."""
        pass

    @abstractmethod
    def apply_fix(self, file_path: pathlib.Path, issue: Dict[str, Any]) -> bool:
        """Applies the fix to the file. Returns True if successful."""
        pass

    @abstractmethod
    def get_description(self, issue: Dict[str, Any]) -> str:
        """Returns a human-readable description of the fix."""
        pass


class GDALImportFixer(FixStrategy):
    """Fixes direct GDAL imports."""

    def can_fix(self, issue: Dict[str, Any]) -> bool:
        return issue.get("type") == "GDAL_DIRECT_IMPORT"

    def apply_fix(self, file_path: pathlib.Path, issue: Dict[str, Any]) -> bool:
        transformer = GDALImportTransformer()
        return apply_transformation(file_path, transformer)

    def get_description(self, issue: Dict[str, Any]) -> str:
        return "Replace 'import gdal' with 'from osgeo import gdal'"


class LegacyImportFixer(FixStrategy):
    """Fixes PyQt4/PyQt5 imports."""

    def can_fix(self, issue: Dict[str, Any]) -> bool:
        return issue.get("type") == "QGIS_LEGACY_IMPORT"

    def apply_fix(self, file_path: pathlib.Path, issue: Dict[str, Any]) -> bool:
        transformer = LegacyImportTransformer()
        return apply_transformation(file_path, transformer)

    def get_description(self, issue: Dict[str, Any]) -> str:
        return "Replace PyQt4/PyQt5 imports with qgis.PyQt"


class PrintToLogFixer(FixStrategy):
    """Fixes print() statements to use QgsMessageLog."""

    def can_fix(self, issue: Dict[str, Any]) -> bool:
        # This would need a new rule type in scanner.py
        return issue.get("type") == "PRINT_STATEMENT"

    def apply_fix(self, file_path: pathlib.Path, issue: Dict[str, Any]) -> bool:
        transformer = PrintToLogTransformer()
        return apply_transformation(file_path, transformer)

    def get_description(self, issue: Dict[str, Any]) -> str:
        return "Replace print() with QgsMessageLog.logMessage()"


class I18nFixer(FixStrategy):
    """Wraps hardcoded UI strings in self.tr()."""

    def can_fix(self, issue: Dict[str, Any]) -> bool:
        return issue.get("type") == "MISSING_I18N"

    def apply_fix(self, file_path: pathlib.Path, issue: Dict[str, Any]) -> bool:
        transformer = I18nTransformer()
        return apply_transformation(file_path, transformer)

    def get_description(self, issue: Dict[str, Any]) -> str:
        return "Wrap hardcoded string in self.tr() for internationalization"


class AutoFixer:
    """Orchestrates the identification and application of auto-fixes.

    Attributes:
        project_path: Root path of the project.
        dry_run: If True, changes are proposed but not written.
        strategies: List of available fix strategies.
    """

    def __init__(self, project_path: pathlib.Path, dry_run: bool = True) -> None:
        """Initializes the auto-fixer.

        Args:
            project_path: Root path of the project.
            dry_run: Whether to run in simulation mode.
        """
        self.project_path = project_path
        self.dry_run = dry_run
        self.strategies: List[FixStrategy] = [
            GDALImportFixer(),
            LegacyImportFixer(),
            PrintToLogFixer(),
            I18nFixer(),
        ]

    def get_fixable_issues(self, issues: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Filters a list of issues to identify those that can be auto-fixed.

        Args:
            issues: A list of issue dictionaries.

        Returns:
            A list of fixable issues, each enriched with a 'fixer' strategy.
        """
        fixable = []
        for issue in issues:
            for strategy in self.strategies:
                if strategy.can_fix(issue):
                    issue["fixer"] = strategy
                    fixable.append(issue)
                    break
        return fixable

    def _check_git_status_with_prompt(self, interactive: bool) -> bool:
        """Checks git status and prompts user if needed. Returns True to continue."""
        if self.dry_run:
            return True

        is_clean = check_git_status(self.project_path)
        if not is_clean:
            print("\n⚠️  WARNING: Working directory has uncommitted changes.")
            print("   It's recommended to commit or stash changes before applying fixes.")
            if interactive:
                response = input("   Continue anyway? [y/N]: ").lower()
                if response != "y":
                    print("Aborted by user.")
                    return False
            print()
        return True

    def _group_issues_by_file(
        self, issues: List[Dict[str, Any]]
    ) -> Dict[str, List[Dict[str, Any]]]:
        """Groups issues by file path."""
        by_file: Dict[str, List[Dict[str, Any]]] = {}
        for issue in issues:
            file_path = issue.get("file", "")
            if file_path not in by_file:
                by_file[file_path] = []
            by_file[file_path].append(issue)
        return by_file

    def _apply_single_fix(
        self,
        file_path: pathlib.Path,
        issue: Dict[str, Any],
        original_content: str,
        interactive: bool,
        stats: Dict[str, int],
    ) -> bool:
        """Applies a single fix and updates stats. Returns True to continue, False to abort."""
        fixer: FixStrategy = issue["fixer"]
        description = fixer.get_description(issue)

        print(f"  Line {issue.get('line', '?')}: {description}")

        if interactive and not self.dry_run:
            # Show diff preview
            with tempfile.NamedTemporaryFile(mode="w", suffix=".py", delete=False) as tmp:
                tmp.write(original_content)
                tmp_path = pathlib.Path(tmp.name)

            try:
                fixer.apply_fix(tmp_path, issue)
                new_content = tmp_path.read_text(encoding="utf-8")

                if new_content != original_content:
                    show_diff(file_path, original_content, new_content)
            finally:
                tmp_path.unlink()

            response = input("    Apply fix? [y/n/q]: ").lower()
            if response == "q":
                print("Aborted by user.")
                return False
            if response != "y":
                stats["skipped"] += 1
                return True

        if not self.dry_run:
            success = fixer.apply_fix(file_path, issue)
            if success:
                stats["applied"] += 1
                print("    ✅ Applied")
            else:
                stats["failed"] += 1
                print("    ❌ Failed")
        else:
            stats["applied"] += 1  # Count as "would apply"

        return True

    def apply_fixes(self, issues: List[Dict[str, Any]], interactive: bool = True) -> Dict[str, int]:
        """Applies fixes to identified issues, grouping by file.

        Args:
            issues: List of issues to fix.
            interactive: Whether to prompt for confirmation and show diffs.

        Returns:
            A dictionary containing processing statistics (applied, skipped, failed).
        """
        stats = {"applied": 0, "skipped": 0, "failed": 0}

        # Git status check
        if not self._check_git_status_with_prompt(interactive):
            return stats

        # Group by file
        by_file = self._group_issues_by_file(issues)

        for file_rel, file_issues in by_file.items():
            file_path = self.project_path / file_rel
            print(f"\n📄 {file_rel}")

            # Read original content for diff
            try:
                original_content = file_path.read_text(encoding="utf-8")
            except Exception as e:
                print(f"  ❌ Error reading file: {e}")
                stats["failed"] += len(file_issues)
                continue

            for issue in file_issues:
                if not self._apply_single_fix(
                    file_path, issue, original_content, interactive, stats
                ):
                    return stats

        return stats

"""Secret detection logic for QGIS Plugin Analyzer.

Handles regex-based matching of API keys and high-entropy string detection.
"""

import math
import re
from dataclasses import dataclass
from typing import List


@dataclass
class SecretFinding:
    """Represents a detected secret or sensitive string."""

    type: str
    message: str
    line: int
    confidence: str


class SecretScanner:
    """Scanner for hardcoded secrets and high-entropy strings."""

    # Common patterns for API keys and tokens
    PATTERNS = {
        "AWS_KEY": r"(?i)AKIA[0-9A-Z]{16}",
        "GOOGLE_API_KEY": r"(?i)AIza[0-9A-Za-z\\-_]{35}",
        "TWILIO_KEY": r"(?i)SK[a-z0-9]{32}",
        "GENERIC_SECRET": r"(?i)(password|secret|passwd|api_key|token|access_key)[\"']?\s*[:=]\s*[\"']?([A-Za-z0-9/+=]{16,})[\"']?",
    }

    def __init__(self):
        self.compiled_patterns = {k: re.compile(v) for k, v in self.PATTERNS.items()}

    def scan_text(self, text: str) -> List[SecretFinding]:
        """Scans a file's content for secrets line by line."""
        findings = []
        lines = text.splitlines()

        for i, line in enumerate(lines, 1):
            # 1. Regex Pattern Matching
            for p_name, pattern in self.compiled_patterns.items():
                match = pattern.search(line)
                if match:
                    findings.append(
                        SecretFinding(
                            type=p_name,
                            message=f"Possible hardcoded secret detected: {p_name}",
                            line=i,
                            confidence="HIGH" if p_name != "GENERIC_SECRET" else "MEDIUM",
                        )
                    )

            # 2. Entropy Analysis for long strings (heuristic)
            # Find strings in double or single quotes
            str_matches = re.finditer(r"[\"']([A-Za-z0-9/+=]{20,})[\"']", line)
            for m in str_matches:
                candidate = m.group(1)
                entropy = self.calculate_entropy(candidate)
                # Shanon entropy: random strings usually > 3.5 - 4.0
                if entropy > 4.5:
                    findings.append(
                        SecretFinding(
                            type="HIGH_ENTROPY",
                            message=f"High-entropy string detected (possible token/key): {candidate[:8]}...",
                            line=i,
                            confidence="MEDIUM",
                        )
                    )

        return findings

    @staticmethod
    def calculate_entropy(data: str) -> float:
        """Calculates Shannon entropy of a string."""
        if not data:
            return 0.0
        entropy = 0.0
        for x in range(256):
            p_x = float(data.count(chr(x))) / len(data)
            if p_x > 0:
                entropy += -p_x * math.log(p_x, 2)
        return entropy

"""Core infrastructure for security scanning in QGIS Plugin Analyzer.

Inspired by Bandit's architecture, this module provides a decorator-based
registry for security checks and a context helper for AST analysis.
"""

import ast
from dataclasses import dataclass
from typing import Any, Callable, Dict, List, Optional, Type


@dataclass
class SecurityFinding:
    """Represents a detected security vulnerability."""

    id: str
    severity: str  # LOW, MEDIUM, HIGH
    confidence: str  # LOW, MEDIUM, HIGH
    message: str
    line: int
    code_snippet: Optional[str] = None
    cwe: Optional[int] = None


class SecurityContext:
    """Helper class providing easy access to AST node information for security checks."""

    def __init__(self, node: ast.AST, filename: str):
        self.node = node
        self.filename = filename

    @property
    def call_function_name(self) -> Optional[str]:
        """Returns the name of the function being called if the node is a Call."""
        if isinstance(self.node, ast.Call):
            if isinstance(self.node.func, ast.Name):
                return self.node.func.id
            if isinstance(self.node.func, ast.Attribute):
                return self.node.func.attr
        return None

    @property
    def call_args_count(self) -> int:
        """Returns the number of positional arguments in a Call node."""
        if isinstance(self.node, ast.Call):
            return len(self.node.args)
        return 0

    def get_call_keyword_value(self, keyword_name: str) -> Any:
        """Returns the value of a specific keyword argument in a Call node."""
        if isinstance(self.node, ast.Call):
            for kw in self.node.keywords:
                if kw.arg == keyword_name:
                    if isinstance(kw.value, ast.Constant):
                        return kw.value.value
        return None


class SecurityRegistry:
    """Registry for security checks managed by decorators."""

    _checks: Dict[Type[ast.AST], List[Callable[[SecurityContext], Optional[SecurityFinding]]]] = {}

    @classmethod
    def register(cls, node_type: Type[ast.AST]) -> Callable:
        """Decorator to register a function as a security check for a specific node type."""

        def decorator(func: Callable[[SecurityContext], Optional[SecurityFinding]]):
            if node_type not in cls._checks:
                cls._checks[node_type] = []
            cls._checks[node_type].append(func)
            return func

        return decorator

    @classmethod
    def get_checks_for_node(
        cls, node_type: Type[ast.AST]
    ) -> List[Callable[[SecurityContext], Optional[SecurityFinding]]]:
        """Returns all registered checks for a given AST node type."""
        return cls._checks.get(node_type, [])


# Decorator alias
security_check = SecurityRegistry.register

"""Security rules for QGIS Plugin Analyzer.

Each check is registered for a specific AST node type and performs a focused
security audit.
"""

import ast
from typing import Optional

from .security_checker import SecurityContext, SecurityFinding, security_check


@security_check(node_type=ast.Call)
def check_exec_eval(context: SecurityContext) -> Optional[SecurityFinding]:
    """B102/B307: Detect use of exec or eval."""
    func_name = context.call_function_name
    if func_name in ("exec", "eval"):
        return SecurityFinding(
            id="B102" if func_name == "exec" else "B307",
            severity="HIGH",
            confidence="HIGH",
            message=f"Use of '{func_name}' detected. This can lead to arbitrary code execution.",
            line=context.node.lineno,
            code_snippet=ast.unparse(context.node),
            cwe=95 if func_name == "eval" else 78,
        )
    return None


@security_check(node_type=ast.Call)
def check_insecure_deserialization(context: SecurityContext) -> Optional[SecurityFinding]:
    """B301: Detect unsafe pickle.load()."""
    if context.call_function_name == "load":
        # Check if it's from 'pickle'
        node = context.node
        if isinstance(node.func, ast.Attribute) and isinstance(node.func.value, ast.Name):
            if node.func.value.id == "pickle":
                return SecurityFinding(
                    id="B301",
                    severity="HIGH",
                    confidence="HIGH",
                    message="Use of 'pickle.load()' detected. Deserializing untrusted data can lead to remote code execution.",
                    line=node.lineno,
                    code_snippet=ast.unparse(node),
                    cwe=502,
                )
    return None


@security_check(node_type=ast.Call)
def check_subprocess_shell(context: SecurityContext) -> Optional[SecurityFinding]:
    """B602: Subprocess call with shell=True."""
    func_name = context.call_function_name
    subprocess_funcs = {"run", "call", "Popen", "check_call", "check_output"}

    if func_name in subprocess_funcs:
        shell_val = context.get_call_keyword_value("shell")
        if shell_val is True:
            return SecurityFinding(
                id="B602",
                severity="HIGH",
                confidence="HIGH",
                message=f"Subprocess call '{func_name}' with 'shell=True' detected. This is a primary source of shell injection.",
                line=context.node.lineno,
                code_snippet=ast.unparse(context.node),
                cwe=78,
            )
    return None


@security_check(node_type=ast.Call)
def check_sql_injection(context: SecurityContext) -> Optional[SecurityFinding]:
    """B608: Basic detection of SQL injection via string formatting."""
    if context.call_function_name == "execute":
        if context.call_args_count > 0:
            sql_arg = context.node.args[0]
            # Check for f-strings or .format() or % formatting in the first argument
            is_unsafe = False
            if isinstance(sql_arg, ast.JoinedStr):
                is_unsafe = True
            elif isinstance(sql_arg, ast.BinOp) and isinstance(sql_arg.op, ast.Mod):
                is_unsafe = True
            elif isinstance(sql_arg, ast.Call) and isinstance(sql_arg.func, ast.Attribute):
                if sql_arg.func.attr == "format":
                    is_unsafe = True

            if is_unsafe:
                return SecurityFinding(
                    id="B608",
                    severity="HIGH",
                    confidence="MEDIUM",
                    message="Possible SQL injection detected. Use parameterized queries instead of string formatting.",
                    line=context.node.lineno,
                    code_snippet=ast.unparse(context.node),
                    cwe=89,
                )
    return None


@security_check(node_type=ast.Assign)
def check_hardcoded_secrets(context: SecurityContext) -> Optional[SecurityFinding]:
    """Detect assignments of sensitive names to constants."""
    node = context.node
    if not isinstance(node, ast.Assign):
        return None

    sensitive_names = {"password", "token", "api_key", "secret", "access_key"}

    for target in node.targets:
        if isinstance(target, ast.Name) and any(s in target.id.lower() for s in sensitive_names):
            if isinstance(node.value, ast.Constant) and isinstance(node.value.value, str):
                # Only flag if it's not empty and looks like a secret
                val = node.value.value
                if len(val) > 8:
                    return SecurityFinding(
                        id="HARDCODED_SECRET",
                        severity="MEDIUM",
                        confidence="MEDIUM",
                        message=f"Possible hardcoded secret in assignment to '{target.id}'.",
                        line=node.lineno,
                        code_snippet=ast.unparse(node),
                    )
    return None

"""Configuration and TOML parsing utilities."""

import logging
import pathlib
import re
from typing import Any, Dict

logger = logging.getLogger("qgis_analyzer")


def _parse_toml_value(val_str: str) -> Any:
    """Converts a TOML value string to appropriate Python type."""
    if val_str.lower() == "true":
        return True
    elif val_str.lower() == "false":
        return False
    elif re.match(r"^-?\d+$", val_str):
        return int(val_str)
    elif (val_str.startswith('"') and val_str.endswith('"')) or (
        val_str.startswith("'") and val_str.endswith("'")
    ):
        return val_str[1:-1]
    return val_str


def _process_section_header(line: str, profile_regex: re.Pattern, rules_regex: re.Pattern) -> tuple:
    """Processes a TOML section header."""
    rules_match = rules_regex.match(line)
    if rules_match:
        return rules_match.group(1), True

    profile_match = profile_regex.match(line)
    if profile_match:
        return profile_match.group(1), False

    return None, False


def _ensure_profile_structure(data: dict, profile_name: str, is_rules: bool) -> None:
    """Ensures the profile structure exists in the data dictionary."""
    if profile_name not in data["tool"]["qgis-analyzer"]["profiles"]:
        data["tool"]["qgis-analyzer"]["profiles"][profile_name] = {}

    if is_rules and "rules" not in data["tool"]["qgis-analyzer"]["profiles"][profile_name]:
        data["tool"]["qgis-analyzer"]["profiles"][profile_name]["rules"] = {}


def _minimal_toml_load(file_obj) -> Dict[str, Any]:
    """EXTREMELY minimal TOML parser for pyproject.toml."""
    data: Dict[str, Any] = {"tool": {"qgis-analyzer": {"profiles": {}}}}
    current_profile = None
    in_rules_section = False

    profile_regex = re.compile(r"^\[tool\.qgis-analyzer\.profiles\.([\w-]+)\]")
    rules_regex = re.compile(r"^\[tool\.qgis-analyzer\.profiles\.([\w-]+)\.rules\]")

    try:
        content = file_obj.read().decode("utf-8")
        for line in content.splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                continue

            if line.startswith("[") and line.endswith("]"):
                profile_name, is_rules = _process_section_header(line, profile_regex, rules_regex)
                if profile_name:
                    current_profile = profile_name
                    in_rules_section = is_rules
                    _ensure_profile_structure(data, current_profile, in_rules_section)
                else:
                    current_profile = None
                    in_rules_section = False
                continue

            if current_profile and "=" in line:
                key, val = line.split("=", 1)
                key = key.strip()
                val = _parse_toml_value(val.strip())

                if in_rules_section:
                    data["tool"]["qgis-analyzer"]["profiles"][current_profile]["rules"][key] = val
                else:
                    data["tool"]["qgis-analyzer"]["profiles"][current_profile][key] = val
    except Exception as e:
        logger.error(f"Error in minimal TOML parser: {e}")

    return data


try:
    import tomllib
except ImportError:
    tomllib = None


def load_profile_config(
    project_path: pathlib.Path, profile_name: str = "default"
) -> Dict[str, Any]:
    """Loads a specific profile configuration from pyproject.toml.

    Args:
        project_path: Root path of the project.
        profile_name: Name of the configuration profile.

    Returns:
        A dictionary containing the profile configuration.
    """
    pyproject = project_path / "pyproject.toml"
    default_config = {
        "strict": False,
        "generate_html": False,
        "fail_on_error": False,
        "rules": {},
    }

    if not pyproject.exists():
        return default_config

    try:
        with open(pyproject, "rb") as f:
            if tomllib:
                import tomllib as tl  # type: ignore

                data = tl.load(f)
            else:
                data = _minimal_toml_load(f)

        profiles = data.get("tool", {}).get("qgis-analyzer", {}).get("profiles", {})
        profile_data = profiles.get(profile_name)

        if not profile_data:
            if profile_name != "default":
                logger.warning(f"Profile '{profile_name}' not found. Using default values.")
            return default_config

        rules_config = profile_data.get("rules", {})

        return {
            **default_config,
            **profile_data,
            "rules": rules_config,
        }
    except Exception as e:
        logger.error(f"Error loading profile: {e}")
        return default_config

"""AST Visitors for QGIS Plugin Analysis."""

import ast
import re
from typing import Any, Dict, List, Optional, Set

# Import to trigger registration of checks
from .rules.qgis_rules import I18N_METHODS
from .security_checker import SecurityContext, SecurityRegistry
from .utils.ast_utils import calculate_complexity


class QGISASTVisitor(ast.NodeVisitor):
    """AST visitor to detect QGIS-specific issues."""

    def __init__(self, rel_path: str, rules_config: Optional[Dict[str, Any]] = None) -> None:
        """Initializes the AST visitor for a specific file.

        Args:
            rel_path: Relative path to the file being analyzed.
            rules_config: Optional configuration for audit rules and severities.
        """
        self.rel_path = rel_path
        self.issues: List[Dict[str, Any]] = []
        self.rules_config = rules_config or {}
        self.class_methods_stack: List[Set[str]] = []

        # New metrics for research-based scoring
        self.docstring_styles: List[str] = []
        self.type_hint_stats = {
            "total_parameters": 0,
            "annotated_parameters": 0,
            "has_return_hint": 0,
            "total_functions": 0,
        }
        self.docstring_stats = {"total_public_items": 0, "has_docstring": 0}
        self.i18n_methods = I18N_METHODS

    def _should_report(self, rule_id: str) -> bool:
        """Check if rule should be reported based on config."""
        severity = self.rules_config.get(rule_id, "warning")
        return bool(severity != "ignore")

    def _get_severity(self, rule_id: str) -> str:
        """Get configured severity for rule (maps to 'high', 'medium', 'low')."""
        config_severity = self.rules_config.get(rule_id, "warning")
        severity_map = {
            "error": "high",
            "warning": "medium",
            "info": "low",
        }
        return severity_map.get(config_severity, "medium")

    def _check_docstring_style(self, doc: Optional[str]) -> None:
        """Identifies Google or NumPy docstring styles within a string."""
        if not doc:
            return
        # Google: Args: or Returns: or Raises: as headers
        if re.search(r"\n\s*(Args|Returns|Raises|Yields):\s*\n", doc):
            self.docstring_styles.append("Google")
        # NumPy: Underlined headers
        elif re.search(r"\n(Parameters|Returns|Raises|Yields)\n\s*-{3,}", doc):
            self.docstring_styles.append("NumPy")

    def _report_issue(self, rule_id: str, line: int, message: str, code: str = "") -> None:
        """Helper to report an issue if enabled."""
        if self._should_report(rule_id):
            self.issues.append(
                {
                    "file": self.rel_path,
                    "line": line,
                    "type": rule_id,
                    "severity": self._get_severity(rule_id),
                    "message": message,
                    "code": code,
                }
            )

    def visit_Module(self, node: ast.Module) -> None:
        """Analyzes a module-level AST node."""
        doc = ast.get_docstring(node)
        self.docstring_stats["total_public_items"] += 1
        if doc:
            self.docstring_stats["has_docstring"] += 1
            self._check_docstring_style(doc)
        else:
            self._report_issue(
                "MISSING_DOCSTRING",
                1,
                "Module is missing a docstring (PEP 257).",
                f"Module: {self.rel_path}",
            )
        self.generic_visit(node)

    def _check_import_name(self, name: str, node: ast.AST, code_snippet: str) -> None:
        """Checks a single import name for violations."""
        # 5. Detect QGIS_PROTECTED_MEMBER
        if name.startswith("qgis._") and not name.startswith("qgis._3d"):
            self._report_issue(
                "QGIS_PROTECTED_MEMBER",
                node.lineno,
                f"Protected member import detected: '{name}'. Protected members are unstable.",
                code_snippet,
            )

        # 6. Detect GDAL_DIRECT_IMPORT
        if name == "gdal":
            self._report_issue(
                "GDAL_DIRECT_IMPORT",
                node.lineno,
                "Direct 'gdal' import detected. Use 'from osgeo import gdal'.",
                code_snippet,
            )

        # Detect QGIS_LEGACY_IMPORT
        if name.startswith(("PyQt4", "PyQt5")):
            self._report_issue(
                "QGIS_LEGACY_IMPORT",
                node.lineno,
                f"Legacy import detected: '{name}'. Use 'qgis.PyQt' for compatibility.",
                code_snippet,
            )

    def visit_Import(self, node: ast.Import) -> None:
        """Analyzes import nodes."""
        for alias in node.names:
            self._check_import_name(alias.name, node, ast.unparse(node))
        self.generic_visit(node)

    def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        """Analyzes 'from import' nodes."""
        if node.module:
            self._check_import_name(node.module, node, ast.unparse(node))

            # 7. Detect HEAVY_LOGIC_UI
            heavy_libs = {"pandas", "numpy", "scipy", "sklearn", "matplotlib"}
            is_ui_file = "gui" in self.rel_path.lower() or "ui" in self.rel_path.lower()
            if is_ui_file and (
                node.module in heavy_libs or node.module.split(".")[0] in heavy_libs
            ):
                self._report_issue(
                    "HEAVY_LOGIC_UI",
                    node.lineno,
                    f"Heavy dependency '{node.module}' detected in UI file. Move logic to core.",
                    ast.unparse(node),
                )
        self.generic_visit(node)

    def _check_docstring_and_metrics(self, node: ast.FunctionDef) -> None:
        """Checks docstrings and collects metrics."""
        if not node.name.startswith("_") and node.name != "__init__":
            doc = ast.get_docstring(node)
            self.docstring_stats["total_public_items"] += 1
            if doc:
                self.docstring_stats["has_docstring"] += 1
                self._check_docstring_style(doc)
            else:
                self._report_issue(
                    "MISSING_DOCSTRING",
                    node.lineno,
                    f"Public function '{node.name}' is missing a docstring.",
                    f"def {node.name}...",
                )

    def _check_type_hints(self, node: ast.FunctionDef) -> None:
        """Checks for type hints."""
        if node.name == "__init__":
            return

        self.type_hint_stats["total_functions"] += 1
        params = [a for a in node.args.args if a.arg != "self" and a.arg != "cls"]
        self.type_hint_stats["total_parameters"] += len(params)
        annotated = [a for a in params if a.annotation]
        self.type_hint_stats["annotated_parameters"] += len(annotated)
        if node.returns:
            self.type_hint_stats["has_return_hint"] += 1

        if params and not annotated and not node.returns:
            self._report_issue(
                "MISSING_TYPE_HINTS",
                node.lineno,
                f"Function '{node.name}' has no type annotations.",
                f"def {node.name}...",
            )

    def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
        """Analyzes function definitions."""
        # IFACE_AS_ARGUMENT
        for arg in node.args.args:
            if arg.annotation and isinstance(arg.annotation, ast.Name):
                if arg.annotation.id == "QgisInterface":
                    self._report_issue(
                        "IFACE_AS_ARGUMENT",
                        node.lineno,
                        f"Function '{node.name}' receives 'QgisInterface' as an argument. Use the global 'iface' or Singleton pattern.",
                        ast.unparse(node).split("\n")[0],
                    )

        # HIGH_COMPLEXITY
        complexity = calculate_complexity(node)
        if complexity > 15:
            self._report_issue(
                "HIGH_COMPLEXITY",
                node.lineno,
                f"Function '{node.name}' is too complex (CC={complexity} > 15). Consider extracting methods.",
                f"def {node.name}...",
            )

        self._check_docstring_and_metrics(node)
        self._check_type_hints(node)
        self.generic_visit(node)

    def visit_ClassDef(self, node: ast.ClassDef) -> None:
        """Analyzes class definitions."""
        methods = {
            item.name
            for item in node.body
            if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef))
        }
        self.class_methods_stack.append(methods)

        # MANDATORY_CLEANUP
        has_init_gui = "initGui" in methods
        has_unload = "unload" in methods

        if has_init_gui and not has_unload:
            self._report_issue(
                "MANDATORY_CLEANUP",
                node.lineno,
                f"Class '{node.name}' implements 'initGui()' but is missing 'unload()'.",
                f"class {node.name}...",
            )

        # Missing Docstring
        if not node.name.startswith("_"):
            doc = ast.get_docstring(node)
            self.docstring_stats["total_public_items"] += 1
            if doc:
                self.docstring_stats["has_docstring"] += 1
                self._check_docstring_style(doc)
            else:
                self._report_issue(
                    "MISSING_DOCSTRING",
                    node.lineno,
                    f"Public class '{node.name}' is missing a docstring.",
                    f"class {node.name}...",
                )

        self.generic_visit(node)
        self.class_methods_stack.pop()

    def visit_Call(self, node: ast.Call) -> None:
        """Analyzes function calls."""
        self._check_obsolete_api(node)
        self._check_missing_i18n(node)
        self._check_missing_slot(node)
        self._check_unsafe_subprocess(node)
        self._check_blocking_network(node)
        self.generic_visit(node)

    # ... Helper check methods (simplified) ...
    def _check_obsolete_api(self, node: ast.Call) -> None:
        if isinstance(node.func, ast.Attribute) and node.func.attr == "writeAsVectorFormat":
            self._report_issue(
                "OBSOLETE_API",
                node.lineno,
                "Obsolete writeAsVectorFormat() usage. Use writeAsVectorFormatV3().",
                ast.unparse(node),
            )

    def _check_missing_i18n(self, node: ast.Call) -> None:
        if isinstance(node.func, ast.Attribute) and node.func.attr in self.i18n_methods:
            if (
                node.args
                and isinstance(node.args[0], ast.Constant)
                and isinstance(node.args[0].value, str)
            ):
                val = node.args[0].value
                if val.strip() and not val.startswith("%"):
                    self._report_issue(
                        "MISSING_I18N",
                        node.lineno,
                        f"Untranslated UI text string in '{node.func.attr}': '{val}'. Use self.tr().",
                        ast.unparse(node),
                    )

    def _check_missing_slot(self, node: ast.Call) -> None:
        if isinstance(node.func, ast.Attribute) and node.func.attr == "connect" and node.args:
            arg = node.args[0]
            if (
                isinstance(arg, ast.Attribute)
                and isinstance(arg.value, ast.Name)
                and arg.value.id == "self"
            ):
                slot = arg.attr
                if self.class_methods_stack and slot not in self.class_methods_stack[-1]:
                    self._report_issue(
                        "POTENTIAL_MISSING_SLOT",
                        node.lineno,
                        f"Connected slot 'self.{slot}' not found in class definitions.",
                    )

    def _check_unsafe_subprocess(self, node: ast.Call) -> None:
        is_subprocess = False
        if isinstance(node.func, ast.Attribute) and isinstance(node.func.value, ast.Name):
            if node.func.value.id == "subprocess" and node.func.attr in {
                "run",
                "call",
                "Popen",
                "check_call",
                "check_output",
            }:
                is_subprocess = True

        if not is_subprocess:
            return

        shell_true = False
        for kw in node.keywords:
            if kw.arg == "shell" and isinstance(kw.value, ast.Constant) and kw.value.value is True:
                shell_true = True
                break

        if shell_true:
            self._report_issue(
                "UNSAFE_SUBPROCESS",
                node.lineno,
                "Subprocess called with 'shell=True'.",
                ast.unparse(node),
            )
            return

        if node.args:
            cmd_arg = node.args[0]
            if isinstance(cmd_arg, (ast.JoinedStr, ast.BinOp)):
                self._report_issue(
                    "UNSAFE_SUBPROCESS",
                    node.lineno,
                    "Possible unquoted variable injection.",
                    ast.unparse(node),
                )

    def _check_blocking_network(self, node: ast.Call) -> None:
        is_network = False
        if isinstance(node.func, ast.Attribute) and isinstance(node.func.value, ast.Name):
            if node.func.value.id == "requests" and node.func.attr in {
                "get",
                "post",
                "put",
                "delete",
                "patch",
            }:
                is_network = True

        if not is_network:
            # Heuristic for urlopen
            attr_chain = []
            curr = node.func
            while isinstance(curr, ast.Attribute):
                attr_chain.append(curr.attr)
                curr = curr.value
            if isinstance(curr, ast.Name):
                attr_chain.append(curr.id)
            if attr_chain == ["urlopen", "request", "urllib"]:
                is_network = True

        if is_network:
            is_ui_file = any(
                kw in self.rel_path.lower() for kw in ["gui", "ui", "dialog", "widget"]
            )
            if is_ui_file:
                self._report_issue(
                    "BLOCKING_NETWORK_CALL",
                    node.lineno,
                    "Synchronous network call detected in UI file.",
                    ast.unparse(node),
                )

    def visit_For(self, node: ast.For) -> None:
        """Analyzes loop nodes."""
        # SPATIAL_INDEX check
        if (
            isinstance(node.iter, ast.Call)
            and isinstance(node.iter.func, ast.Attribute)
            and node.iter.func.attr == "getFeatures"
        ):
            warn = False
            if not node.iter.args:
                warn = True
            elif len(node.iter.args) == 1:
                arg = node.iter.args[0]
                if (
                    isinstance(arg, ast.Call)
                    and isinstance(arg.func, ast.Name)
                    and arg.func.id == "QgsFeatureRequest"
                ):
                    if not arg.args and not arg.keywords:
                        warn = True

            if warn:
                self._report_issue(
                    "SPATIAL_INDEX",
                    node.lineno,
                    "Iteration over features with getFeatures() and no filter.",
                    ast.unparse(node.iter),
                )

        # NON_PYTHONIC_LOOP
        for body_node in ast.walk(node):
            if isinstance(body_node, ast.AugAssign) and isinstance(body_node.op, ast.Add):
                if (
                    isinstance(body_node.target, ast.Name)
                    and isinstance(body_node.value, ast.Constant)
                    and body_node.value.value == 1
                ):
                    self._report_issue(
                        "NON_PYTHONIC_LOOP",
                        body_node.lineno,
                        f"Manual counter '{body_node.target.id} += 1' detected inside loop.",
                        ast.unparse(body_node),
                    )

        self.generic_visit(node)


class QGISSecurityVisitor(ast.NodeVisitor):
    """AST visitor focused on security vulnerabilities (Bandit-inspired)."""

    def __init__(self, rel_path: str):
        self.rel_path = rel_path
        self.findings: List[Dict[str, Any]] = []

    def visit(self, node: ast.AST):
        """Dispatches security checks for the current node."""
        checks = SecurityRegistry.get_checks_for_node(type(node))
        context = SecurityContext(node, self.rel_path)

        for check_func in checks:
            finding = check_func(context)
            if finding:
                self.findings.append(
                    {
                        "file": self.rel_path,
                        "line": finding.line,
                        "type": finding.id,
                        "severity": finding.severity.lower(),
                        "message": finding.message,
                        "code": finding.code_snippet,
                        "confidence": finding.confidence.lower()
                        if hasattr(finding, "confidence")
                        else "medium",
                    }
                )

        super().generic_visit(node)
